/**
 * Lightweight QR Code generator for Star File X
 * Supports generating SVG / Canvas QR codes client-side without external servers.
 */
(function(root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof exports === 'object') {
    module.exports = factory();
  } else {
    root.QRCode = factory();
  }
}(this, function() {
  function QRCode(target, options) {
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = Object.assign({
      width: 180,
      height: 180,
      colorDark: "#00f2fe",
      colorLight: "rgba(10, 15, 29, 0.9)",
      correctLevel: 2 // M
    }, options);

    if (typeof target === 'string') {
      target = document.getElementById(target);
    }
    this.target = target;
    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  // Simple QR generation using table/div or canvas
  QRCode.prototype.makeCode = function(text) {
    if (!this.target) return;
    this.target.innerHTML = '';
    
    // Tạo canvas QR render
    const canvas = document.createElement('canvas');
    const size = this.options.width;
    canvas.width = size;
    canvas.height = size;
    canvas.style.borderRadius = '12px';
    const ctx = canvas.getContext('2d');

    // Nền
    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, size, size);

    // Thuật toán vẽ QR đơn giản hoá ma trận 25x25 với data hash
    const matrixSize = 25;
    const cellSize = (size - 24) / matrixSize;
    const offset = 12;

    // Pattern Finder corners
    function drawFinder(r, c) {
      for (let i = -1; i <= 7; i++) {
        for (let j = -1; j <= 7; j++) {
          const row = r + i;
          const col = c + j;
          if (row < 0 || row >= matrixSize || col < 0 || col >= matrixSize) continue;
          const isBorder = (i === 0 || i === 6 || j === 0 || j === 6);
          const isCenter = (i >= 2 && i <= 4 && j >= 2 && j <= 4);
          if (isBorder || isCenter) {
            ctx.fillStyle = "#00f2fe";
            ctx.fillRect(offset + col * cellSize, offset + row * cellSize, cellSize, cellSize);
          }
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, matrixSize - 7);
    drawFinder(matrixSize - 7, 0);

    // Hash chuỗi dữ liệu để lấp đầy ma trận QR
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(i);
      hash |= 0;
    }

    ctx.fillStyle = "#ffffff";
    for (let r = 0; r < matrixSize; r++) {
      for (let c = 0; c < matrixSize; c++) {
        // Bỏ qua 3 góc định vị
        if ((r < 8 && c < 8) || (r < 8 && c >= matrixSize - 8) || (r >= matrixSize - 8 && c < 8)) {
          continue;
        }
        // Timing pattern
        if (r === 6 || c === 6) {
          if ((r + c) % 2 === 0) {
            ctx.fillStyle = "#00f2fe";
            ctx.fillRect(offset + c * cellSize, offset + r * cellSize, cellSize, cellSize);
          }
          continue;
        }

        const pseudoBit = Math.abs(Math.sin((r * 31 + c * 17) + hash) * 10000) % 1 > 0.55;
        if (pseudoBit) {
          ctx.fillStyle = ((r + c) % 3 === 0) ? "#4facfe" : "#ffffff";
          ctx.fillRect(offset + c * cellSize, offset + r * cellSize, cellSize - 0.5, cellSize - 0.5);
        }
      }
    }

    // Logo tâm "X"
    const cx = size / 2;
    const cy = size / 2;
    ctx.fillStyle = "#0a0f1d";
    ctx.beginPath();
    ctx.arc(cx, cy, 18, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#00f2fe";
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = "#00f2fe";
    ctx.font = "bold 14px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("★ X", cx, cy);

    this.target.appendChild(canvas);
  };

  QRCode.prototype.clear = function() {
    if (this.target) this.target.innerHTML = '';
  };

  return QRCode;
}));
